async function previewCode(raw,lang){$('previewTitle').textContent=lang==='mermaid'?'流程图预览':'内容预览';$('previewBody').replaceChildren();$('previewDialog').showModal();if(lang==='mermaid'){const box=E('div','正在生成流程图…','mermaid-result');$('previewBody').append(box);try{if(!window.mermaid)throw Error('流程图库未加载');mermaid.initialize({startOnLoad:false,securityLevel:'strict',flowchart:{htmlLabels:false},theme:state.settings.theme==='dark'?'dark':'default'});const r=await mermaid.render('m'+uid().replaceAll('-',''),raw);box.innerHTML=DOMPurify.sanitize(r.svg,{USE_PROFILES:{svg:true}});}catch(e){box.textContent='流程图语法无法渲染：'+e.message;}return;}const frame=E('iframe',undefined,'preview-frame');frame.setAttribute('sandbox','allow-scripts');frame.title='隔离的生成内容预览';frame.srcdoc='<!doctype html><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'; script-src \'unsafe-inline\'; img-src data: blob:; font-src data:; connect-src \'none\'; form-action \'none\';"><style>body{font-family:system-ui;padding:16px;overflow-wrap:anywhere}img,svg{max-width:100%}</style>'+raw;$('previewBody').append(frame);}
async function previewAsset(id){const a=state.assets.find(a=>a.id===id);if(!a)return;$('previewTitle').textContent=a.name;const body=$('previewBody');body.replaceChildren();$('previewDialog').showModal();const url=await assetURL(id);if(['image','audio','video'].includes(a.kind)){const n=E(a.kind==='image'?'img':a.kind);if(a.kind==='image'){n.alt=a.name;n.className='preview-img';}else n.controls=true;n.src=url;body.append(n);}else if(a.text!==null&&a.text!==undefined)body.append(E('pre',a.text||a.parseError||'没有可显示的文字'));else body.append(E('p','该格式保留为原文件，请下载后使用对应应用打开。'));body.append(B('下载原文件',()=>downloadAsset(id)));}
function renderSessions(){const nav=$('sessions'),q=$('sessionSearch').value.trim().toLowerCase();nav.replaceChildren();const sessions=state.sessions.filter(s=>!q||s.title.toLowerCase().includes(q)||s.messages.some(m=>(m.text||'').toLowerCase().includes(q))).sort((a,b)=>b.updated.localeCompare(a.updated));$('sessionCount').textContent=sessions.length;for(const s of sessions){const row=E('div',undefined,'session'+(s.id===state.activeSession?' active':'')),button=B('',()=>switchSession(s.id),'session-main');button.append(E('strong',s.title),E('small',date(s.updated)+' · '+s.messages.length+' 条'));row.append(button,B('×',()=>deleteSession(s.id),'session-delete'));nav.append(row);}if(!sessions.length)nav.append(E('p','没有匹配的会话','small'));$('renameChat').textContent=current().title;}
