function collectMessage(m,assets=m.assets||[],text=m.text){const note={id:uid(),bookId:book().id,title:'',text:text||'',original:text||'',originalReasoning:m.reasoning||'',time:now(),tags:'',star:false,assets:[...assets],source:{sessionId:current().id,messageId:m.id,model:m.model||m.role,time:m.time},editing:true};state.notes.unshift(note);renderNotes();saveSoon();clearSelection();toast('已加入「'+book().title+'」，可直接编辑');}
function renderBooks(){const select=$('notebook');select.replaceChildren();state.notebooks.forEach(b=>{const o=E('option',b.title);o.value=b.id;select.append(o);});select.value=book().id;}
function renderNotes(){const host=$('notes'),q=$('noteSearch').value.toLowerCase(),filter=$('noteFilter').value;host.replaceChildren();const notes=state.notes.filter(n=>n.bookId===book().id&&(!q||[n.text,n.title,n.tags,n.source?.model].join(' ').toLowerCase().includes(q))&&(filter==='all'||filter==='star'&&n.star||filter==='text'&&!n.assets.length||n.assets.some(id=>state.assets.find(a=>a.id===id)?.kind===filter))).sort((a,b)=>Number(b.star)-Number(a.star));$('noteCount').textContent=notes.length+' 条笔记';if(!notes.length){const e=E('div',undefined,'notes-empty');e.append(E('div','▤','empty-symbol'),E('strong',q||filter!=='all'?'没有匹配的笔记':'让知识在这里生长'),E('p',q||filter!=='all'?'试试其他关键词或类型。':'选中回答中的一段，点击「加入笔记」。\n图片、音频、视频和文件，也能一起留下。'));host.append(e);return;}notes.forEach(n=>host.append(noteCard(n)));}
function noteCard(n){const card=E('article',undefined,'note');card.dataset.noteId=n.id;const meta=E('div',undefined,'note-meta'),kindLabel=n.assets.length?'多模态摘录':n.source?'AI 摘录':'我的理解';meta.append(E('span',kindLabel,'note-type'),E('time',date(n.time)),B(n.star?'★':'☆',()=>{n.star=!n.star;renderNotes();saveSoon();},n.star?'starred':''),B('×',()=>deleteNote(n.id)));card.append(meta);const title=E('input',undefined,'note-title');title.value=n.title;title.placeholder='添加一个标题…';title.setAttribute('aria-label','笔记标题');title.oninput=()=>{n.title=title.value;saveSoon();};card.append(title);const editor=E('textarea',undefined,'note-editor');editor.value=n.text;editor.placeholder='写下你的理解，支持 Markdown、代码、公式…';editor.setAttribute('aria-label','编辑笔记');editor.oninput=()=>{n.text=editor.value;saveSoon();};const preview=E('div',undefined,'rendered');renderRich(n.text,preview);if(n.editing===false){editor.hidden=true;}else preview.hidden=true;card.append(editor,preview);if(n.assets.length)card.append(assetsView(n.assets,{remove:id=>{n.assets=n.assets.filter(x=>x!==id);renderNotes();saveSoon();}}));const bottom=E('div',undefined,'note-bottom'),tags=E('input',undefined,'note-tags');tags.value=n.tags;tags.placeholder='# 添加标签，用逗号分隔';tags.setAttribute('aria-label','笔记标签');tags.oninput=()=>{n.tags=tags.value;saveSoon();};const toggle=B(n.editing===false?'编辑':'预览',()=>{n.editing=n.editing===false;editor.hidden=n.editing===false;preview.hidden=n.editing!==false;if(n.editing===false)renderRich(n.text,preview);toggle.textContent=n.editing===false?'编辑':'预览';saveSoon();});const move=E('select');move.setAttribute('aria-label','移动笔记到笔记本');for(const b of state.notebooks){const o=E('option',b.title);o.value=b.id;move.append(o);}move.value=n.bookId;move.onchange=()=>{n.bookId=move.value;renderNotes();saveSoon();toast('笔记已移动，原始摘录保留');};if(state.notebooks.length>1)bottom.append(move);bottom.append(tags,toggle,B('附件',()=>{noteAttachmentTarget=n.id;$('noteAttachmentInput').click();}),B('带入对话',()=>noteToChat(n)));card.append(bottom);if(n.source){const details=E('details',undefined,'source'),summary=E('summary','来源 · '+n.source.model+' · 查看原始摘录');details.append(summary,E('pre',n.original||'该笔记摘录了附件，原始文件见上方。'));if(n.originalReasoning)details.append(E('pre','原始思考过程：\n'+n.originalReasoning));details.append(B('回到原对话',()=>jumpSource(n)));card.append(details);}return card;}
function deleteNote(id){const n=state.notes.find(n=>n.id===id);state.trash.push({kind:'note',value:structuredClone(n),deleted:now()});state.notes=state.notes.filter(n=>n.id!==id);saveSoon();renderNotes();toast('已移到本地回收记录，可在设置中撤销');}
function undoDelete(){const t=state.trash.pop();if(!t){toast('没有可恢复的记录');return;}if(t.kind==='note')state.notes.unshift(t.value);else state.sessions.push(t.value);renderSessions();renderNotes();saveSoon();toast('已恢复最近删除的内容');}
function noteToChat(n){if(busy){toast('请等当前回答结束');return;}current().draft.text='请围绕这条笔记继续讨论：\n\n'+n.text;current().draft.assets=[...new Set([...current().draft.assets,...n.assets])];$('prompt').value=current().draft.text;renderPending();saveSoon();setMobile('chat');toast('笔记已放入输入框，发送前可编辑');}
function jumpSource(n){const session=state.sessions.find(s=>s.id===n.source?.sessionId);if(!session){toast('来源会话已删除，原始摘录仍保留');return;}switchSession(session.id);setMobile('chat');const m=$('message-'+n.source.messageId);if(m){m.scrollIntoView({behavior:'smooth',block:'center'});m.classList.add('highlight-flash');setTimeout(()=>m.classList.remove('highlight-flash'),1800);}}
function renderPending(){$('pending').replaceChildren(assetsView(current().draft.assets,{remove:id=>{current().draft.assets=current().draft.assets.filter(x=>x!==id);renderPending();saveSoon();}}));}
function editMessage(m){$('editHeading').textContent=m.role==='user'?'编辑并重新提问':'编辑回答记录';$('editTitle').value='';$('editTitle').parentElement.hidden=true;$('editText').value=m.text;$('editHelp').textContent=m.role==='user'?'保存后会建立一条新会话分支，保留原对话。附件会一并保留；点击发送后再请求模型。':'只修改本地回答记录，已摘录的笔记保留原始版本。';editAction=()=>{if(busy){toast('请先停止当前回答');return;}if(m.role==='user'){const source=current(),index=source.messages.indexOf(m),s={id:uid(),title:source.title+' · 分支',created:now(),updated:now(),messages:structuredClone(source.messages.slice(0,index)),draft:{text:$('editText').value,assets:[...(m.assets||[])]}};s.messages.forEach(x=>x.id=uid());state.sessions.push(s);state.activeSession=s.id;$('prompt').value=s.draft.text;renderPending();}else{m.text=$('editText').value;m.edited=now();}renderMessages();renderSessions();saveSoon();$('editDialog').close();};$('editDialog').showModal();}
const DEVICE_KEY_STORAGE='picked-device-credential-v1';
function readDeviceKey(){try{const value=JSON.parse(localStorage.getItem(DEVICE_KEY_STORAGE));return value?.version===1&&typeof value.base==='string'&&typeof value.key==='string'&&value.key.trim()?value:null;}catch{return null;}}
function forgetDeviceKey(){try{localStorage.removeItem(DEVICE_KEY_STORAGE);return true;}catch{return false;}}
function rememberDeviceKey(base,key){try{localStorage.setItem(DEVICE_KEY_STORAGE,JSON.stringify({version:1,base,key}));return true;}catch{forgetDeviceKey();return false;}}
function restoreDeviceKey(){const saved=readDeviceKey();if(saved?.base===state.settings.base){apiKey=saved.key;connectedBase=saved.base;}}
function openSettings(){$('rememberKey').checked=readDeviceKey()?.base===state.settings.base;$('provider').value=state.settings.provider;$('base').value=state.settings.base;$('model').value=state.settings.model;$('key').value='';$('key').placeholder=apiKey?'已连接；留空沿用当前 Key':'仅保留在本次页面内存中';$('vision').checked=state.settings.vision;$('systemPrompt').value=state.settings.system;$('settingsDialog').showModal();storageInfo();}
function updateConnection(){const connected=!!apiKey&&connectedBase===state.settings.base;$('connection').textContent=connected?'● 已连接配置':'○ 待连接';$('connection').classList.toggle('connected',connected);$('modelButton').textContent=state.settings.model+(connected?' · 已配置':' · 填写 Key');$('thinking').setAttribute('aria-pressed',String(state.settings.thinking));$('thinking').disabled=!state.settings.base.includes('api.deepseek.com');document.body.classList.toggle('dark',state.settings.theme==='dark');}
async function buildMessages(messages){const result=[];if(state.settings.system)result.push({role:'system',content:state.settings.system});let total=0;for(const m of messages){if(m.status==='error'&&!m.text)continue;let text=m.text||'';const images=[];for(const id of m.assets||[]){const a=state.assets.find(a=>a.id===id);if(!a)continue;if(m.role==='user'&&a.kind==='image'&&state.settings.vision){if(a.type==='image/svg+xml')throw Error('SVG 请转换为 PNG 或 JPEG 后再用于图片识别');const blob=await getBlob(id);if(blob)images.push({type:'image_url',image_url:{url:await dataURL(blob)}});else if(a.url)images.push({type:'image_url',image_url:{url:a.url}});}else if(a.text)text+='\n\n[附件 '+a.name+' 的提取文字]\n'+a.text;else text+='\n[记录附件：'+a.name+'；该附件内容未提供给模型]';}const content=images.length?[{type:'text',text:text||'请解释图片'},...images]:text;total+=JSON.stringify(content).length;if(total>32*1048576)throw Error('上下文超过本工具的 32 MB 请求上限，请新建会话或减少附件');result.push({role:m.role,content});}return result;}
async function send(){if(busy||stale||uploading)return;if(!apiKey||connectedBase!==state.settings.base){openSettings();toast('请先填写并应用模型 API Key');return;}const text=$('prompt').value.trim(),ids=[...current().draft.assets];if(!text&&!ids.length)return;const m={id:uid(),role:'user',text:text||'请查看附件。',assets:ids,time:now(),status:'done'};current().messages.push(m);if(current().title==='新对话')current().title=text.slice(0,25)||'附件讨论';current().updated=now();current().draft={text:'',assets:[]};$('prompt').value='';renderPending();renderMessages();renderSessions();await persist();await generate();}
async function generate(context=null){if(busy||stale||uploading)return;if(!apiKey||connectedBase!==state.settings.base){openSettings();toast('请先连接模型');return;}const s=current(),source=context||s.messages;const target={id:uid(),role:'assistant',text:'',reasoning:'',assets:[],time:now(),model:state.settings.model,status:'streaming'};s.messages.push(target);busy=true;activeGeneration={session:s.id,message:target.id};$('send').disabled=true;$('stop').hidden=false;controller=new AbortController();renderMessages();toast('模型正在回答…');let timer,lastRender=0,scrollPinned=true;const timeout=setTimeout(()=>controller.abort('timeout'),180000);timer=setInterval(()=>persist(),5000);const refresh=()=>{if(performance.now()-lastRender<90)return;lastRender=performance.now();const article=$('message-'+target.id);if(!article)return;scrollPinned=$('messages').scrollHeight-$('messages').scrollTop-$('messages').clientHeight<180;const body=article.querySelector('.message-content');body.textContent=target.text||'正在思考…';if(scrollPinned)$('messages').scrollTop=$('messages').scrollHeight;};try{const messages=await buildMessages(source.filter(m=>m!==target));const body={model:state.settings.model,messages,stream:true};if(state.settings.base.includes('api.deepseek.com'))body.thinking={type:state.settings.thinking?'enabled':'disabled'};const base=state.settings.base.replace(/\/$/,''),endpoint=base.endsWith('/chat/completions')?base:base+'/chat/completions';if(typeof captureRequest==='function')await captureRequest(target,body,endpoint);const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+apiKey},body:JSON.stringify(body),signal:controller.signal});if(!response.ok){let detail='';try{const r=await response.json();detail=r.error?.message||'';}catch{}throw Error('HTTP '+response.status+(detail?'：'+detail.slice(0,350):''));}
 const absorb=async data=>{if(data.error)throw Error(data.error.message||'模型返回错误');const choice=data.choices?.[0],d=choice?.delta||choice?.message;if(data.usage)target.usage=data.usage;if(!d)return;if(typeof d.content==='string')target.text+=d.content;else if(Array.isArray(d.content)){for(const p of d.content){if(p.type==='text')target.text+=p.text||'';else if(p.type==='image_url'&&p.image_url?.url)await addOutputMedia(target,p.image_url.url,'image');}}if(d.reasoning_content)target.reasoning+=d.reasoning_content;for(const image of d.images||[])if(image.image_url?.url)await addOutputMedia(target,image.image_url.url,'image');if(d.audio?.data)await addOutputMedia(target,'data:audio/'+(d.audio.format||'wav')+';base64,'+d.audio.data,'audio');refresh();};
 if(response.headers.get('content-type')?.includes('application/json'))await absorb(await response.json());else{if(!response.body)throw Error('响应没有可读数据');const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='',eventData=[];async function line(value){if(!value.trim()){if(eventData.length){const raw=eventData.join('\n');eventData=[];if(raw!=='[DONE]'){let data;try{data=JSON.parse(raw);}catch{throw Error('接口返回了无效的流式数据');}await absorb(data);}}}else if(value.startsWith('data:'))eventData.push(value.slice(5).trimStart());}while(true){const {value,done}=await reader.read();buffer+=decoder.decode(value||new Uint8Array(),{stream:!done});let index;while((index=buffer.indexOf('\n'))>=0){const value=buffer.slice(0,index).replace(/\r$/,'');buffer=buffer.slice(index+1);await line(value);}if(done){if(buffer)await line(buffer.replace(/\r$/,''));await line('');break;}}}
 if(!target.text&&!target.assets.length)throw Error('接口没有返回可显示的内容');target.status='done';toast('回答完成，可以选中内容加入笔记');}catch(e){target.status='error';target.error=controller.signal.aborted?(controller.signal.reason==='timeout'?'请求超过 3 分钟，已停止；已接收内容保留。':'已停止生成，已接收内容保留。'):'请求失败：'+e.message+'。可检查配置后重新生成。';toast(target.error);}finally{clearTimeout(timeout);clearInterval(timer);busy=false;activeGeneration=null;$('send').disabled=false;$('stop').hidden=true;s.updated=now();renderMessages();renderSessions();await persist();}}
async function addOutputMedia(target,url,type){if(target.assets.some(id=>state.assets.find(a=>a.id===id)?.url===url))return;const id=uid();if(url.startsWith('data:')){const m=url.match(/^data:([^;,]+);base64,(.*)$/s);if(!m)return;const binary=atob(m[2]);if(binary.length>25*1048576)throw Error('模型输出附件超过 25 MB 上限');const blob=new Blob([Uint8Array.from(binary,c=>c.charCodeAt(0))],{type:m[1]});await putBlob(id,blob);state.assets.push({id,name:'AI 输出 '+type,type:m[1],size:blob.size,kind:type,time:now(),text:null});}else{const safe=safeHTTP(url);if(!safe)return;state.assets.push({id,name:'AI 输出 '+type,url:safe,type:type+'/*',size:0,kind:type,time:now(),text:null,remote:true});}target.assets.push(id);}
async function regenerate(id){if(busy)return;const s=current(),index=s.messages.findIndex(m=>m.id===id);const context=s.messages.slice(0,index);if(!context.some(m=>m.role==='user')){toast('这条导入的回答没有前置提问，请先输入问题');return;}await generate(context);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('已复制');}catch{const area=E('textarea');area.value=text;document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();toast(ok?'已复制':'复制失败，请手动选择文字');}}
function speak(text){if(!('speechSynthesis'in window)){toast('当前浏览器不支持朗读');return;}if(speechSynthesis.speaking){speechSynthesis.cancel();toast('已停止朗读');return;}if(text.length>20000)toast('本次朗读前 2 万字符，完整内容仍保留');const u=new SpeechSynthesisUtterance(text.replace(/[`#*]/g,'').slice(0,20000));u.lang='zh-CN';u.onerror=e=>toast('朗读未完成：'+e.error);speechSynthesis.speak(u);toast('开始朗读，再次点击可停止');}
async function toggleRecording(){if(recording){recording.stop();return;}if(!window.MediaRecorder||!navigator.mediaDevices?.getUserMedia){toast('当前浏览器不支持录音，请上传音频文件');return;}try{recorderStream=await navigator.mediaDevices.getUserMedia({audio:true});const type=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(t=>MediaRecorder.isTypeSupported(t));const rec=new MediaRecorder(recorderStream,type?{mimeType:type}:undefined);recording=rec;const chunks=[];rec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};rec.onstop=async()=>{clearTimeout(rec._limit);recorderStream.getTracks().forEach(t=>t.stop());recording=null;$('voice').textContent='◉ 录音';const blob=new Blob(chunks,{type:rec.mimeType});if(!blob.size){toast('未录到音频');return;}const ext=rec.mimeType.includes('mp4')?'m4a':'webm';const ids=await ingest([new File([blob],'语音备忘录-'+Date.now()+'.'+ext,{type:blob.type})]);current().draft.assets.push(...ids);renderPending();saveSoon();toast('录音已保存到附件，可播放和记笔记；当前模型不转写音频');};rec.onerror=()=>{toast('录音发生错误，请重试');rec.stop();};rec.start();rec._limit=setTimeout(()=>rec.state!=='inactive'&&rec.stop(),300000);$('voice').textContent='■ 停止录音';toast('正在录音，再次点击停止（最长 5 分钟）');}catch(e){recorderStream?.getTracks().forEach(t=>t.stop());toast('无法录音：'+(e.name==='NotAllowedError'?'麦克风权限未授予':e.message));}}
function setupDictation(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return;$('dictate').hidden=false;let active=null;$('dictate').onclick=()=>{if(active){active.stop();return;}const sr=new SR();sr.lang='zh-CN';sr.interimResults=false;sr.continuous=true;sr.onresult=e=>{for(let i=e.resultIndex;i<e.results.length;i++)if(e.results[i].isFinal)$('prompt').value+=e.results[i][0].transcript;current().draft.text=$('prompt').value;saveSoon();};sr.onerror=e=>toast('语音输入不可用：'+e.error+'，可改用录音附件');sr.onend=()=>{active=null;$('dictate').textContent='语音输入';};try{sr.start();active=sr;$('dictate').textContent='停止听写';toast('语音转文字由浏览器识别服务提供');}catch(e){toast(e.message);}};}
function setMobile(view){document.body.classList.toggle('show-notes',view==='notes');document.querySelectorAll('[data-mobile]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mobile===view)));}
let noteAttachmentTarget=null;
function renderLibrary(){const host=$('library'),q=$('librarySearch').value.toLowerCase();host.replaceChildren();const ids=state.assets.filter(a=>a.name.toLowerCase().includes(q)).map(a=>a.id);if(!ids.length){host.append(E('p','还没有附件。上传的原文件会保存在这里。','small'));return;}const list=assetsView(ids,{collect:id=>{const n={id:uid(),bookId:book().id,title:'',text:'',original:'',time:now(),tags:'',assets:[id],source:null,star:false};state.notes.unshift(n);renderNotes();saveSoon();toast('附件已加入笔记本');}});list.style.display='contents';host.append(list);}
async function storageInfo(){try{const info=await navigator.storage.estimate();$('storageInfo').textContent='本机已用 '+bytes(info.usage||0)+' / 可用配额 '+bytes(info.quota||0)+' · '+state.assets.length+' 个附件。浏览器清除网站数据会删除本地资料，请定期备份。';}catch{$('storageInfo').textContent='请定期备份，浏览器清除网站数据会删除本地资料。';}}
function downloadURL(name,url){const a=E('a');a.download=name;a.href=url;document.body.append(a);a.click();a.remove();}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));downloadURL(name,url);setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function backup(){await persist();toast('正在打包全部文字和原文件…');const assets=[];for(const a of state.assets){const blob=await getBlob(a.id);assets.push({...a,data:blob?await dataURL(blob):null});}const snapshot=structuredClone(state);snapshot.assets=assets;download('Picked-完整备份-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({format:'picked-workspace',version:2,created:now(),workspace:snapshot}),'application/json');toast('备份已生成，包含 '+assets.length+' 个附件；不包含 API Key');}
function validateWorkspace(s){if(!s||s.schema!==2||!Array.isArray(s.sessions)||!s.sessions.length||!Array.isArray(s.notebooks)||!s.notebooks.length||!Array.isArray(s.notes)||!Array.isArray(s.assets))throw Error('备份结构不完整');const ids=new Set();for(const list of [s.sessions,s.notebooks,s.notes,s.assets])for(const x of list){if(!x||typeof x.id!=='string'||ids.has(x.id))throw Error('备份标识无效或重复');ids.add(x.id);}for(const x of s.sessions){if(typeof x.title!=='string'||!Array.isArray(x.messages))throw Error('会话格式无效');x.draft=x.draft||{text:'',assets:[]};if(!Array.isArray(x.draft.assets)||typeof x.draft.text!=='string')throw Error('草稿格式无效');for(const m of x.messages){if(!['user','assistant'].includes(m.role)||typeof m.text!=='string'||!Array.isArray(m.assets))throw Error('消息格式无效');if(m.status==='streaming'){m.status='error';m.error='该回答在备份前尚未完成，可重新生成';}}}for(const n of s.notes){if(typeof n.text!=='string'||!Array.isArray(n.assets))throw Error('笔记格式无效');n.tags=typeof n.tags==='string'?n.tags:'';n.title=typeof n.title==='string'?n.title:'';}for(const a of s.assets){if(typeof a.name!=='string'||!['image','audio','video','file'].includes(a.kind))throw Error('附件格式无效');if(a.url&&!safeHTTP(a.url))throw Error('远程附件链接无效');if(a.data&&!/^data:[\w.+/-]+;base64,[A-Za-z0-9+/=\s]+$/.test(a.data))throw Error('附件编码无效');}return s;}
async function importBackup(file){if(busy){toast('请先停止回答');return;}if(file.size>350*1048576){toast('备份超过 350 MB，无法导入');return;}let raw;try{raw=JSON.parse(await file.text());}catch{throw Error('不是有效的 JSON 文件');}const incoming=raw.format==='picked-workspace'?validateWorkspace(raw.workspace):raw.messages&&raw.notes?migrate(raw):null;if(!incoming)throw Error('不是 Picked 备份');if(!await confirmAction('将备份合并到当前资料，保留已有内容。'))return;const idmap=new Map(),map=id=>idmap.get(id)||id;for(const x of [...incoming.sessions,...incoming.notebooks,...incoming.notes,...incoming.assets])idmap.set(x.id,uid());for(const s of incoming.sessions)for(const m of s.messages)idmap.set(m.id,uid());for(const a of incoming.assets){const old=a.id;a.id=map(old);if(a.data){const match=a.data.match(/^data:([^;,]+);base64,(.*)$/s);if(!match)throw Error('附件编码无效');const binary=atob(match[2]);await putBlob(a.id,new Blob([Uint8Array.from(binary,c=>c.charCodeAt(0))],{type:match[1]}));delete a.data;}state.assets.push(a);}const remapText=t=>typeof t==='string'?t.replace(/asset:([a-zA-Z0-9-]+)/g,(full,id)=>'asset:'+map(id)):t;for(const s of incoming.sessions){s.id=map(s.id);s.messages.forEach(m=>{m.id=map(m.id);m.assets=m.assets.map(map);m.text=remapText(m.text);});s.draft.assets=s.draft.assets.map(map);if(s.materials){s.materials.excludedMessages=(s.materials.excludedMessages||[]).map(map);s.materials.excludedAssets=(s.materials.excludedAssets||[]).map(map);s.materials.noteIds=(s.materials.noteIds||[]).map(map);}for(const m of s.messages)if(m.requestRecord?.assets)m.requestRecord.assets=m.requestRecord.assets.map(map);s.title+=' · 导入';state.sessions.push(s);}for(const b of incoming.notebooks){b.id=map(b.id);b.title+=' · 导入';state.notebooks.push(b);}for(const n of incoming.notes){n.id=map(n.id);n.bookId=map(n.bookId);n.assets=n.assets.map(map);n.text=remapText(n.text);n.original=remapText(n.original);if(n.derivedFrom)n.derivedFrom=map(n.derivedFrom);for(const v of n.versions||[])if(v.snapshot?.assets)v.snapshot.assets=v.snapshot.assets.map(map);if(n.review?.base?.assets){n.review.base.assets=n.review.base.assets.map(map);n.review.baseSignature=JSON.stringify(n.review.base);}for(const receipt of [n.review?.request,n.aiRequest])if(receipt?.assets)receipt.assets=receipt.assets.map(map);if(n.source){n.source.sessionId=map(n.source.sessionId);n.source.messageId=map(n.source.messageId);}state.notes.push(n);}await persist();renderSessions();renderBooks();renderNotes();toast('导入完成，原有内容已保留');}
function exportItems(){return exportScope==='chat'?current().messages.map(m=>({title:m.role==='user'?'你':m.model||'AI',text:m.text,assets:m.assets,time:m.time,source:null})):state.notes.filter(n=>n.bookId===book().id);}
async function exportContent(format){$('exportDialog').close();if(format==='json'){await backup();return;}const items=exportItems(),title=exportScope==='chat'?current().title:book().title;const markdown='# '+title+'\n\n'+items.map(n=>'## '+(n.title||'记录')+(n.knowledgeState?'\n\n知识状态：'+n.knowledgeState:'')+'\n\n'+n.text+(n.assets.length?'\n\n'+n.assets.map(id=>{const a=state.assets.find(a=>a.id===id);return a?'附件：'+a.name+'（原文件保存在 JSON 备份）':'';}).join('\n'):'')+(n.source?'\n\n来源：'+n.source.model+' · '+n.source.time:'')).join('\n\n---\n\n');if(format==='md'){download(title+'.md',markdown,'text/markdown');return;}
 const root=E('main');root.append(E('h1',title));let remoteCount=0;for(const n of items){const article=E('article'),h=E('h2',n.title||'记录'),content=E('div',undefined,'rendered');renderRich(n.text,content);article.append(h);if(n.knowledgeState)article.append(E('p','知识状态：'+n.knowledgeState));article.append(content);if(n.assets?.length)article.append(assetsView(n.assets));for(const b of content.querySelectorAll('button')){if(b.classList.contains('remote-media')){b.replaceWith(E('p',b.title+'（远程图片链接）'));remoteCount++;}else b.remove();}for(const id of n.assets||[]){const a=state.assets.find(a=>a.id===id);if(a?.url)remoteCount++;}root.append(article);}
 const media=[...root.querySelectorAll('[data-asset-id]')];for(const card of media){const id=card.dataset.assetId,a=state.assets.find(a=>a.id===id),blob=await getBlob(id);const url=blob?await dataURL(blob):a?.url;const node=card.querySelector('img,audio,video');if(node&&url)node.src=url;card.querySelectorAll('button.asset-preview').forEach(b=>b.replaceWith(...b.childNodes));card.querySelectorAll('button').forEach(b=>b.remove());if(a?.kind==='file'&&url){const link=E('a','下载 '+a.name);link.href=url;link.download=a.name;card.prepend(link);}}
 const style='.katex-html{display:none}body{font:15px/1.85 system-ui;max-width:960px;margin:40px auto;padding:0 24px;color:#222}article{border-bottom:1px solid #ddd;padding:20px 0}pre{white-space:pre-wrap;background:#f5f5f7;padding:16px}img,video{max-width:100%;max-height:600px}audio{width:100%}table{border-collapse:collapse}td,th{border:1px solid #ddd;padding:8px}a{color:#505bc8}.code-bar{font-size:12px;color:#777}.asset-card{padding:10px 0}.asset-detail{font-size:12px;color:#777}';const html='<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>'+escapeHTML(title)+'</title><style>'+style+'</style>'+root.outerHTML+'</html>';if(format==='html'){download(title+'.html',html,'text/html');toast(remoteCount?'已导出；远程媒体仍需要网络，建议上传原文件后再备份':'离线 HTML 已导出');}else{const frame=E('iframe');frame.style.display='none';frame.srcdoc=html;document.body.append(frame);frame.onload=()=>{frame.contentWindow.print();setTimeout(()=>frame.remove(),60000);};}}
function escapeHTML(s){const n=E('span',s);return n.innerHTML;}
