(async()=>{try{state=await initDB();if(!state){try{const old=JSON.parse(localStorage.getItem('picked-notebook-v1'));state=old?migrate(old):fresh();}catch{state=fresh();}}savedRevision=state.revision||0;state.trash=state.trash||[];for(const s of state.sessions){s.draft=s.draft||{text:'',assets:[]};for(const m of s.messages)if(m.status==='streaming'){m.status='error';m.error='上次生成因页面关闭而中断，可重新生成。';}}}catch(e){state=fresh();toast('无法打开本地资料库：'+e.message+'；请勿关闭页面，先导出内容');}setupEvents();restoreDeviceKey();updateConnection();renderSessions();renderBooks();renderMessages();renderNotes();renderPending();$('prompt').value=current().draft.text;await persist();window.pickedReady=true;window.dispatchEvent(new Event('picked:ready'));})();
